//! Durable approval storage and matching for remote targets.
//!
//! Approvals are persisted to SQLite and restored after restart so equivalent
//! requests can be auto-approved without re-prompting the user.

mod remote_approval;
mod store;

pub use remote_approval::{ApprovalMatcher, RemoteTargetApproval};
pub use store::{ApprovalStore, ApprovalStoreError};

use crate::{ApprovalId, ApprovalRequest, ApprovalResolution};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// A stored approval decision with context for matching future requests.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct StoredApproval {
    pub id: ApprovalId,
    pub action_fingerprint: String,
    pub capability_version: Option<u32>,
    pub intent_revision: u64,
    pub accepted: bool,
    pub created_at_unix_ms: u64,
    /// Remote target context for approval matching.
    pub remote_context: Option<RemoteTargetApproval>,
}

impl StoredApproval {
    pub fn from_resolution(
        resolution: &ApprovalResolution,
        request: &ApprovalRequest,
    ) -> Self {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock after epoch")
            .as_millis() as u64;

        Self {
            id: resolution.id,
            action_fingerprint: resolution.action_fingerprint.to_string(),
            capability_version: request.capability_version,
            intent_revision: resolution.intent_revision,
            accepted: resolution.accepted,
            created_at_unix_ms: now,
            remote_context: RemoteTargetApproval::extract_from_action(&request.action),
        }
    }

    /// Check if this stored approval matches a new request.
    pub fn matches(&self, request: &ApprovalRequest) -> bool {
        if !self.accepted {
            return false;
        }

        // Fingerprint must match exactly
        if self.action_fingerprint != request.action_fingerprint.to_string() {
            return false;
        }

        // Capability version must match if present
        if self.capability_version != request.capability_version {
            return false;
        }

        // For remote contexts, use specialized matcher
        if let Some(ref stored_context) = self.remote_context {
            if let Some(request_context) = RemoteTargetApproval::extract_from_action(&request.action)
            {
                let matcher = ApprovalMatcher::new(stored_context);
                return matcher.matches(&request_context);
            }
            return false;
        }

        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{Action, ActionKind, ActionOrigin, ApprovalState};

    #[test]
    fn stored_approval_rejects_denied_approvals() {
