            summary: "write file2".into(),
            target: Some("file2.txt".into()),
        };

        let request1 = ApprovalRequest {
            id: Uuid::new_v4(),
            action: action1.clone(),
            action_fingerprint: crate::policy::ActionFingerprint::for_action(&action1),
            capability_version: None,
            intent_revision: 1,
            reason: "test".into(),
            state: ApprovalState::Pending,
        };

        let request2 = ApprovalRequest {
            id: Uuid::new_v4(),
