            resolver: crate::ApprovalResolver::User,
        };

        let stored = StoredApproval::from_resolution(&resolution, &request1);

        assert!(!stored.matches(&request2));
    }
}

//! Remote target approval context and matching.
//!
//! Captures SSH host keys, remote file paths, and tmux sessions for precise
//! approval matching across restarts.

use crate::{Action, ActionKind};
use serde::{Deserialize, Serialize};

/// Remote target context for durable approval matching.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct RemoteTargetApproval {
    /// SSH host key fingerprint for host identity verification.
    pub host_key: String,
    /// Remote file path or working directory.
    pub remote_path: String,
    /// Optional tmux session identifier.
    pub tmux_session: Option<String>,
    /// Operation type for fine-grained matching.
    pub operation: RemoteOperation,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RemoteOperation {
    SshConnect,
    SftpRead,
    SftpWrite,
    TmuxAttach,
    TmuxCommand,
}

impl RemoteTargetApproval {
    /// Extract remote context from an Action if it's a remote operation.
    pub fn extract_from_action(action: &Action) -> Option<Self> {
        match action.kind {
            ActionKind::SshConnect => {
                let target = action.target.as_ref()?;
                Self::parse_ssh_target(target, RemoteOperation::SshConnect)
            }
            ActionKind::SftpTransfer => {
                let target = action.target.as_ref()?;
                let operation = if action.summary.contains("read") || action.summary.contains("download") {
                    RemoteOperation::SftpRead
                } else {
                    RemoteOperation::SftpWrite
                };
                Self::parse_ssh_target(target, operation)
            }
            ActionKind::TmuxAttach => {
                let target = action.target.as_ref()?;
                Self::parse_tmux_target(target)
            }
            _ => None,
        }
    }

    fn parse_ssh_target(target: &str, operation: RemoteOperation) -> Option<Self> {
        // Expected format: "host_key@host:path" or "host_key@host"
        let parts: Vec<&str> = target.splitn(2, '@').collect();
        if parts.len() != 2 {
            return None;
        }

        let host_key = parts[0].to_string();
        let rest = parts[1];

        let (remote_path, tmux_session) = if let Some(colon_idx) = rest.find(':') {
            let path = rest[colon_idx + 1..].to_string();
            (path, None)
        } else {
            (String::new(), None)
        };

        Some(Self {
            host_key,
            remote_path,
            tmux_session,
            operation,
        })
    }

    fn parse_tmux_target(target: &str) -> Option<Self> {
        // Expected format: "host_key@host:session_name:path"
        let parts: Vec<&str> = target.splitn(2, '@').collect();
        if parts.len() != 2 {
            return None;
        }

        let host_key = parts[0].to_string();
        let rest = parts[1];

        let components: Vec<&str> = rest.splitn(3, ':').collect();
        let (tmux_session, remote_path) = match components.len() {
            1 => (None, String::new()),
            2 => (Some(components[1].to_string()), String::new()),
            3 => (Some(components[1].to_string()), components[2].to_string()),
            _ => return None,
        };

        Some(Self {
            host_key,
            remote_path,
            tmux_session,
            operation: RemoteOperation::TmuxAttach,
        })
    }
}

/// Matches new remote approval requests against stored approvals.
pub struct ApprovalMatcher<'a> {
    stored: &'a RemoteTargetApproval,
}

impl<'a> ApprovalMatcher<'a> {
    pub fn new(stored: &'a RemoteTargetApproval) -> Self {
        Self { stored }
    }

    /// Check if a new request matches the stored approval.
    pub fn matches(&self, request: &RemoteTargetApproval) -> bool {
        // Host key must match exactly
        if self.stored.host_key != request.host_key {
            return false;
        }

        // Operation must match exactly
        if self.stored.operation != request.operation {
            return false;
        }

        // Tmux session must match if present in stored approval
        if self.stored.tmux_session.is_some()
            && self.stored.tmux_session != request.tmux_session
        {
            return false;
        }

        // Remote path must match or request must be a subpath
        if !request.remote_path.is_empty() && !self.stored.remote_path.is_empty() {
            // Allow exact match or subpath access
            if request.remote_path != self.stored.remote_path
                && !request.remote_path.starts_with(&format!("{}/", self.stored.remote_path))
            {
                return false;
            }
        }

        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ActionOrigin;

    #[test]
    fn extract_ssh_connect_from_action() {
        let action = Action {
            origin: ActionOrigin::Agent,
