        };

        let matcher = ApprovalMatcher::new(&stored);
        assert!(!matcher.matches(&request));
    }

    #[test]
    fn matcher_allows_subpath_access() {
        let stored = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/home/user".into(),
            tmux_session: None,
            operation: RemoteOperation::SftpRead,
        };

        let request = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/home/user/documents/file.txt".into(),
            tmux_session: None,
            operation: RemoteOperation::SftpRead,
        };

        let matcher = ApprovalMatcher::new(&stored);
        assert!(matcher.matches(&request));
    }

    #[test]
    fn matcher_rejects_parent_path_access() {
        let stored = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/home/user/documents".into(),
            tmux_session: None,
            operation: RemoteOperation::SftpRead,
        };

        let request = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/home/user".into(),
            tmux_session: None,
            operation: RemoteOperation::SftpRead,
        };

        let matcher = ApprovalMatcher::new(&stored);
        assert!(!matcher.matches(&request));
    }

    #[test]
    fn matcher_requires_tmux_session_match() {
        let stored = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/workspace".into(),
            tmux_session: Some("session1".into()),
            operation: RemoteOperation::TmuxAttach,
        };

        let request = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/workspace".into(),
            tmux_session: Some("session2".into()),
            operation: RemoteOperation::TmuxAttach,
        };

        let matcher = ApprovalMatcher::new(&stored);
        assert!(!matcher.matches(&request));
    }

    #[test]
    fn matcher_accepts_matching_context() {
        let stored = RemoteTargetApproval {
            host_key: "sha256:abc123".into(),
            remote_path: "/home/user".into(),
            tmux_session: Some("dev".into()),
            operation: RemoteOperation::TmuxAttach,
        };

        let request = stored.clone();

        let matcher = ApprovalMatcher::new(&stored);
        assert!(matcher.matches(&request));
    }
}

//! SQLite-backed durable approval storage.
//!
//! Stores approval decisions with remote context and restores them after restart.

use super::{RemoteTargetApproval, StoredApproval};
use crate::{ApprovalId, ApprovalRequest};
use rusqlite::{params, Connection, TransactionBehavior};
use std::path::Path;
use std::sync::{Arc, Mutex};
use thiserror::Error;
use uuid::Uuid;

#[derive(Debug, Error)]
pub enum ApprovalStoreError {
    #[error("storage lock poisoned")]
    Poisoned,
    #[error(transparent)]
    Sqlite(#[from] rusqlite::Error),
    #[error(transparent)]
    Json(#[from] serde_json::Error),
    #[error("approval `{0}` not found")]
    NotFound(ApprovalId),
    #[error("invalid UUID `{0}`")]
    InvalidUuid(String),
}

pub trait ApprovalStore: Send + Sync {
    /// Save an approval decision.
    fn save(&self, approval: &StoredApproval) -> Result<(), ApprovalStoreError>;

    /// Find a matching stored approval for a new request.
    fn find_match(&self, request: &ApprovalRequest) -> Result<Option<StoredApproval>, ApprovalStoreError>;

    /// Load all stored approvals.
    fn load_all(&self) -> Result<Vec<StoredApproval>, ApprovalStoreError>;

    /// Delete an approval by ID.
    fn delete(&self, id: ApprovalId) -> Result<(), ApprovalStoreError>;
}

pub struct SqliteApprovalStore {
    connection: Mutex<Connection>,
}

impl SqliteApprovalStore {
    pub fn open(path: impl AsRef<Path>) -> Result<Arc<Self>, ApprovalStoreError> {
        let connection = Connection::open(path)?;
        connection.execute_batch(
            "PRAGMA journal_mode = WAL;
             PRAGMA foreign_keys = ON;
             CREATE TABLE IF NOT EXISTS approvals (
                id TEXT PRIMARY KEY,
                action_fingerprint TEXT NOT NULL,
                capability_version INTEGER,
                intent_revision INTEGER NOT NULL,
                accepted INTEGER NOT NULL,
                created_at_unix_ms INTEGER NOT NULL,
                remote_context_json TEXT
             );
             CREATE INDEX IF NOT EXISTS approvals_fingerprint_idx ON approvals(action_fingerprint);
             CREATE INDEX IF NOT EXISTS approvals_created_idx ON approvals(created_at_unix_ms DESC);",
        )?;
        Ok(Arc::new(Self {
            connection: Mutex::new(connection),
        }))
    }

    pub fn in_memory() -> Result<Arc<Self>, ApprovalStoreError> {
        Self::open(":memory:")
    }
}

impl ApprovalStore for SqliteApprovalStore {
    fn save(&self, approval: &StoredApproval) -> Result<(), ApprovalStoreError> {
        let mut conn = self.connection.lock().map_err(|_| ApprovalStoreError::Poisoned)?;
        let transaction = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;

        let remote_context_json = approval
            .remote_context
            .as_ref()
            .map(|ctx| serde_json::to_string(ctx))
            .transpose()?;

        transaction.execute(
            "INSERT OR REPLACE INTO approvals 
             (id, action_fingerprint, capability_version, intent_revision, accepted, created_at_unix_ms, remote_context_json)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
            params![
                approval.id.to_string(),
                approval.action_fingerprint,
                approval.capability_version,
                approval.intent_revision,
                approval.accepted as i32,
                approval.created_at_unix_ms,
                remote_context_json,
            ],
        )?;

        transaction.commit()?;
        Ok(())
    }

    fn find_match(&self, request: &ApprovalRequest) -> Result<Option<StoredApproval>, ApprovalStoreError> {
        let conn = self.connection.lock().map_err(|_| ApprovalStoreError::Poisoned)?;

        // Query all approvals with matching fingerprint
        let mut statement = conn.prepare(
            "SELECT id, action_fingerprint, capability_version, intent_revision, accepted, created_at_unix_ms, remote_context_json
             FROM approvals 
             WHERE action_fingerprint = ?1 AND accepted = 1
             ORDER BY created_at_unix_ms DESC"
        )?;

        let rows = statement.query_map(
            [request.action_fingerprint.to_string()],
            |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, Option<u32>>(2)?,
                    row.get::<_, u64>(3)?,
                    row.get::<_, i32>(4)?,
                    row.get::<_, u64>(5)?,
                    row.get::<_, Option<String>>(6)?,
                ))
            },
        )?;

        for row in rows {
            let (id, action_fingerprint, capability_version, intent_revision, accepted, created_at_unix_ms, remote_context_json) = row?;

            let id = Uuid::parse_str(&id)
                .map_err(|_| ApprovalStoreError::InvalidUuid(id.clone()))?;

            let remote_context = remote_context_json
                .map(|json| serde_json::from_str::<RemoteTargetApproval>(&json))
                .transpose()?;

            let stored = StoredApproval {
                id,
                action_fingerprint,
                capability_version,
                intent_revision,
                accepted: accepted != 0,
                created_at_unix_ms,
                remote_context,
            };

            if stored.matches(request) {
                return Ok(Some(stored));
            }
        }

        Ok(None)
    }

    fn load_all(&self) -> Result<Vec<StoredApproval>, ApprovalStoreError> {
        let conn = self.connection.lock().map_err(|_| ApprovalStoreError::Poisoned)?;

        let mut statement = conn.prepare(
            "SELECT id, action_fingerprint, capability_version, intent_revision, accepted, created_at_unix_ms, remote_context_json
             FROM approvals
             ORDER BY created_at_unix_ms DESC"
        )?;

        let rows = statement.query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, Option<u32>>(2)?,
                row.get::<_, u64>(3)?,
                row.get::<_, i32>(4)?,
                row.get::<_, u64>(5)?,
                row.get::<_, Option<String>>(6)?,
            ))
        })?;

        rows.map(|row| {
            let (id, action_fingerprint, capability_version, intent_revision, accepted, created_at_unix_ms, remote_context_json) = row?;

            let id = Uuid::parse_str(&id)
                .map_err(|_| ApprovalStoreError::InvalidUuid(id.clone()))?;

            let remote_context = remote_context_json
                .map(|json| serde_json::from_str::<RemoteTargetApproval>(&json))
                .transpose()?;

            Ok(StoredApproval {
                id,
                action_fingerprint,
                capability_version,
                intent_revision,
                accepted: accepted != 0,
                created_at_unix_ms,
                remote_context,
            })
        })
        .collect()
    }

    fn delete(&self, id: ApprovalId) -> Result<(), ApprovalStoreError> {
        let mut conn = self.connection.lock().map_err(|_| ApprovalStoreError::Poisoned)?;
        let transaction = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;

        let changed = transaction.execute(
            "DELETE FROM approvals WHERE id = ?1",
            params![id.to_string()],
        )?;

        if changed == 0 {
            return Err(ApprovalStoreError::NotFound(id));
        }

        transaction.commit()?;
        Ok(())
    }
}

