            kind: ActionKind::SshConnect,
            summary: "ssh connect".into(),
            target: Some(target.into()),
        };

        ApprovalRequest {
            id: Uuid::new_v4(),
            action,
            action_fingerprint: crate::policy::ActionFingerprint::for_action(&Action {
                origin: ActionOrigin::Agent,
                kind: ActionKind::SshConnect,
                summary: "ssh connect".into(),
                target: Some(target.into()),
            }),
            capability_version: None,
            intent_revision: 1,
            reason: "test".into(),
            state: ApprovalState::Pending,
        }
    }

    #[test]
    fn save_and_load_approval() {
        let store = SqliteApprovalStore::in_memory().expect("create in-memory store");
        let request = create_test_request("sha256:abc123@example.com:/home/user");

        let resolution = ApprovalResolution {
            id: request.id,
            action_fingerprint: request.action_fingerprint.clone(),
            intent_revision: request.intent_revision,
            accepted: true,
            resolver: ApprovalResolver::User,
        };

        let stored = StoredApproval::from_resolution(&resolution, &request);
        store.save(&stored).expect("save approval");

        let loaded = store.load_all().expect("load approvals");
        assert_eq!(loaded.len(), 1);
        assert_eq!(loaded[0].id, stored.id);
        assert_eq!(loaded[0].action_fingerprint, stored.action_fingerprint);
    }

    #[test]
    fn find_match_returns_matching_approval() {
        let store = SqliteApprovalStore::in_memory().expect("create in-memory store");
        let request1 = create_test_request("sha256:abc123@example.com:/home/user");

        let resolution = ApprovalResolution {
            id: request1.id,
            action_fingerprint: request1.action_fingerprint.clone(),
            intent_revision: request1.intent_revision,
            accepted: true,
            resolver: ApprovalResolver::User,
        };

        let stored = StoredApproval::from_resolution(&resolution, &request1);
        store.save(&stored).expect("save approval");

        // Same request should match
        let request2 = create_test_request("sha256:abc123@example.com:/home/user");
        let found = store.find_match(&request2).expect("find match");
        assert!(found.is_some());
        assert_eq!(found.unwrap().id, stored.id);
    }

    #[test]
    fn find_match_rejects_different_host_key() {
        let store = SqliteApprovalStore::in_memory().expect("create in-memory store");
        let request1 = create_test_request("sha256:abc123@example.com:/home/user");

        let resolution = ApprovalResolution {
            id: request1.id,
            action_fingerprint: request1.action_fingerprint.clone(),
            intent_revision: request1.intent_revision,
            accepted: true,
            resolver: ApprovalResolver::User,
        };

        let stored = StoredApproval::from_resolution(&resolution, &request1);
        store.save(&stored).expect("save approval");

        // Different host key should not match
        let request2 = create_test_request("sha256:different@example.com:/home/user");
        let found = store.find_match(&request2).expect("find match");
        assert!(found.is_none());
    }

    #[test]
    fn delete_removes_approval() {
        let store = SqliteApprovalStore::in_memory().expect("create in-memory store");
        let request = create_test_request("sha256:abc123@example.com:/home/user");

        let resolution = ApprovalResolution {
            id: request.id,
            action_fingerprint: request.action_fingerprint.clone(),
            intent_revision: request.intent_revision,
            accepted: true,
            resolver: ApprovalResolver::User,
        };

        let stored = StoredApproval::from_resolution(&resolution, &request);
        store.save(&stored).expect("save approval");

        store.delete(stored.id).expect("delete approval");

        let loaded = store.load_all().expect("load approvals");
        assert_eq!(loaded.len(), 0);
    }

    #[test]
    fn rejected_approvals_are_not_matched() {
        let store = SqliteApprovalStore::in_memory().expect("create in-memory store");
        let request = create_test_request("sha256:abc123@example.com:/home/user");

        let resolution = ApprovalResolution {
            id: request.id,
            action_fingerprint: request.action_fingerprint.clone(),
            intent_revision: request.intent_revision,
            accepted: false,
            resolver: ApprovalResolver::User,
        };

        let stored = StoredApproval::from_resolution(&resolution, &request);
        store.save(&stored).expect("save approval");

        let found = store.find_match(&request).expect("find match");
        assert!(found.is_none());
    }

    #[test]
    fn approval_survives_store_reopen() {
        let temp_dir = std::env::temp_dir().join(format!("approval-store-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&temp_dir).expect("create temp dir");
        let db_path = temp_dir.join("approvals.db");

        let request = create_test_request("sha256:abc123@example.com:/home/user");

        {
            let store = SqliteApprovalStore::open(&db_path).expect("create store");

            let resolution = ApprovalResolution {
                id: request.id,
                action_fingerprint: request.action_fingerprint.clone(),
                intent_revision: request.intent_revision,
                accepted: true,
                resolver: ApprovalResolver::User,
            };

            let stored = StoredApproval::from_resolution(&resolution, &request);
            store.save(&stored).expect("save approval");
        }

        // Reopen store and verify approval persisted
        {
            let store = SqliteApprovalStore::open(&db_path).expect("reopen store");
            let found = store.find_match(&request).expect("find match after restart");
            assert!(found.is_some());
            assert_eq!(found.unwrap().id, request.id);
        }

        std::fs::remove_dir_all(temp_dir).expect("cleanup temp dir");
    }
}

