    pub fn user(request: &ApprovalRequest, accepted: bool) -> Self {
        Self {
            id: request.id,
            action_fingerprint: request.action_fingerprint.clone(),
            intent_revision: request.intent_revision,
            accepted,
            resolver: ApprovalResolver::User,
        }
