//! Integration test for v0.6 gate: durable approval for remote targets.
//!
//! Gate criteria:
//! - RemoteTargetApproval captures host-key, remote path, tmux session
//! - Approvals persist to SQLite and survive restart
//! - ApprovalMatcher correctly matches equivalent remote requests
//! - Remote approval remains valid after harness restart

use impetus_core::{
    Action, ActionKind, ActionOrigin, ApprovalRequest, ApprovalResolution, ApprovalResolver,
    ApprovalState, ApprovalStore, RemoteOperation, RemoteTargetApproval, SqliteApprovalStore,
    StoredApproval,
};
use std::path::PathBuf;
use uuid::Uuid;

fn temp_approval_db() -> PathBuf {
    let root = std::env::temp_dir().join(format!("v06-gate-{}", Uuid::new_v4()));
    std::fs::create_dir_all(&root).expect("create workspace");
    root.join("approvals.db")
}

fn create_ssh_request(target: &str) -> ApprovalRequest {
    let action = Action {
        origin: ActionOrigin::Agent,
        kind: ActionKind::SshConnect,
        summary: "ssh connect".into(),
        target: Some(target.into()),
    };

    ApprovalRequest {
        id: Uuid::new_v4(),
        action: action.clone(),
        action_fingerprint: impetus_core::policy::ActionFingerprint::for_action(&action),
        capability_version: None,
        intent_revision: 1,
        reason: "connect to remote server".into(),
        state: ApprovalState::Pending,
    }
}

fn create_sftp_request(target: &str, operation: &str) -> ApprovalRequest {
    let action = Action {
        origin: ActionOrigin::Agent,
        kind: ActionKind::SftpTransfer,
        summary: format!("{} remote file", operation),
        target: Some(target.into()),
    };

    ApprovalRequest {
        id: Uuid::new_v4(),
        action: action.clone(),
        action_fingerprint: impetus_core::policy::ActionFingerprint::for_action(&action),
        capability_version: None,
        intent_revision: 1,
        reason: format!("{} file via sftp", operation),
        state: ApprovalState::Pending,
    }
}

fn create_tmux_request(target: &str) -> ApprovalRequest {
    let action = Action {
        origin: ActionOrigin::Agent,
        kind: ActionKind::TmuxAttach,
        summary: "attach to tmux session".into(),
        target: Some(target.into()),
    };

    ApprovalRequest {
        id: Uuid::new_v4(),
        action: action.clone(),
        action_fingerprint: impetus_core::policy::ActionFingerprint::for_action(&action),
        capability_version: None,
        intent_revision: 1,
        reason: "attach to remote tmux".into(),
        state: ApprovalState::Pending,
    }
}

#[test]
fn remote_target_approval_extracts_ssh_context() {
    let request = create_ssh_request("sha256:abc123@example.com:/home/user");
    let context = RemoteTargetApproval::extract_from_action(&request.action).unwrap();

    assert_eq!(context.host_key, "sha256:abc123");
    assert_eq!(context.remote_path, "/home/user");
    assert_eq!(context.operation, RemoteOperation::SshConnect);
    assert_eq!(context.tmux_session, None);
}

#[test]
fn remote_target_approval_extracts_tmux_context() {
    let request = create_tmux_request("sha256:xyz789@remote.com:dev_session:/workspace");
    let context = RemoteTargetApproval::extract_from_action(&request.action).unwrap();

    assert_eq!(context.host_key, "sha256:xyz789");
    assert_eq!(context.remote_path, "/workspace");
    assert_eq!(context.tmux_session, Some("dev_session".to_string()));
    assert_eq!(context.operation, RemoteOperation::TmuxAttach);
}

#[test]
fn approval_persists_to_sqlite() {
    let db_path = temp_approval_db();
    let store = SqliteApprovalStore::open(&db_path).expect("open store");

    let request = create_ssh_request("sha256:abc123@example.com:/home/user");
    let resolution = ApprovalResolution {
        id: request.id,
        action_fingerprint: request.action_fingerprint.clone(),
        intent_revision: request.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    let stored = StoredApproval::from_resolution(&resolution, &request);
    store.save(&stored).expect("save approval");

    let loaded = store.load_all().expect("load all approvals");
    assert_eq!(loaded.len(), 1);
    assert_eq!(loaded[0].id, stored.id);
    assert!(loaded[0].remote_context.is_some());
}

#[test]
fn approval_survives_restart() {
    let db_path = temp_approval_db();

    let request = create_ssh_request("sha256:abc123@example.com:/home/user");
    let resolution = ApprovalResolution {
        id: request.id,
        action_fingerprint: request.action_fingerprint.clone(),
        intent_revision: request.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    // Save approval in first session
    {
        let store = SqliteApprovalStore::open(&db_path).expect("open store");
        let stored = StoredApproval::from_resolution(&resolution, &request);
        store.save(&stored).expect("save approval");
    }

    // Restart: open new store and verify approval still exists
    {
        let store = SqliteApprovalStore::open(&db_path).expect("reopen store");
        let new_request = create_ssh_request("sha256:abc123@example.com:/home/user");
        let found = store.find_match(&new_request).expect("find match");

        assert!(found.is_some());
        let matched = found.unwrap();
        assert_eq!(matched.id, request.id);
        assert!(matched.remote_context.is_some());
    }
}

#[test]
fn approval_matcher_rejects_different_host_key() {
    let db_path = temp_approval_db();
    let store = SqliteApprovalStore::open(&db_path).expect("open store");

    let request1 = create_ssh_request("sha256:abc123@example.com:/home/user");
    let resolution = ApprovalResolution {
        id: request1.id,
        action_fingerprint: request1.action_fingerprint.clone(),
        intent_revision: request1.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    let stored = StoredApproval::from_resolution(&resolution, &request1);
    store.save(&stored).expect("save approval");

    // Different host key should not match
    let request2 = create_ssh_request("sha256:different@example.com:/home/user");
    let found = store.find_match(&request2).expect("find match");
    assert!(found.is_none());
}

#[test]
fn approval_matcher_allows_subpath_access() {
    let db_path = temp_approval_db();
    let store = SqliteApprovalStore::open(&db_path).expect("open store");

    let request1 = create_sftp_request("sha256:abc123@example.com:/data", "read");
    let resolution = ApprovalResolution {
        id: request1.id,
        action_fingerprint: request1.action_fingerprint.clone(),
        intent_revision: request1.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    let stored = StoredApproval::from_resolution(&resolution, &request1);
    store.save(&stored).expect("save approval");

    // Subpath access should match
    let request2 = create_sftp_request("sha256:abc123@example.com:/data/subdir/file.txt", "read");
    let found = store.find_match(&request2).expect("find match");
    assert!(found.is_some());
}

#[test]
fn approval_matcher_rejects_parent_path_access() {
    let db_path = temp_approval_db();
    let store = SqliteApprovalStore::open(&db_path).expect("open store");

    let request1 = create_sftp_request("sha256:abc123@example.com:/data/subdir", "read");
    let resolution = ApprovalResolution {
        id: request1.id,
        action_fingerprint: request1.action_fingerprint.clone(),
        intent_revision: request1.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    let stored = StoredApproval::from_resolution(&resolution, &request1);
    store.save(&stored).expect("save approval");

    // Parent path access should not match
    let request2 = create_sftp_request("sha256:abc123@example.com:/data", "read");
    let found = store.find_match(&request2).expect("find match");
    assert!(found.is_none());
}

#[test]
fn approval_matcher_distinguishes_read_write_operations() {
    let db_path = temp_approval_db();
    let store = SqliteApprovalStore::open(&db_path).expect("open store");

    let read_request = create_sftp_request("sha256:abc123@example.com:/data/file.txt", "read");
    let resolution = ApprovalResolution {
        id: read_request.id,
        action_fingerprint: read_request.action_fingerprint.clone(),
        intent_revision: read_request.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    let stored = StoredApproval::from_resolution(&resolution, &read_request);
    store.save(&stored).expect("save approval");

    // Write operation should not match read approval
    let write_request = create_sftp_request("sha256:abc123@example.com:/data/file.txt", "write");
    let found = store.find_match(&write_request).expect("find match");
    assert!(found.is_none());
}

#[test]
fn approval_matcher_requires_tmux_session_match() {
    let db_path = temp_approval_db();
    let store = SqliteApprovalStore::open(&db_path).expect("open store");

    let request1 = create_tmux_request("sha256:abc123@remote.com:session1:/workspace");
    let resolution = ApprovalResolution {
        id: request1.id,
        action_fingerprint: request1.action_fingerprint.clone(),
        intent_revision: request1.intent_revision,
        accepted: true,
        resolver: ApprovalResolver::User,
    };

    let stored = StoredApproval::from_resolution(&resolution, &request1);
    store.save(&stored).expect("save approval");

    // Different tmux session should not match
    let request2 = create_tmux_request("sha256:abc123@remote.com:session2:/workspace");
    let found = store.find_match(&request2).expect("find match");
    assert!(found.is_none());
}

#[test]
