//! Controlled process/PTY execution with sandbox checks and resource limits.
//!
//! This module provides safe PTY capabilities following the v0.5 capability SDK pattern:
//! - Sandbox check before PTY spawn (fail-closed)
//! - PolicyCheck for process execution (command, args, env, working_dir)
//! - Resource limits (timeout, memory, CPU)
//! - Process lifecycle: spawn, write stdin, read output, signal, wait/kill

use crate::{
    Action, ActionOrigin, CapabilityVersion, EffectAdmission, EffectCapability, EffectSeam,
    NormalizedEffect, Sandbox,
};
use portable_pty::{CommandBuilder, MasterPty, PtySize, PtySystem};
use std::collections::HashMap;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum PtyError {
    #[error("PTY spawn failed: {0}")]
    SpawnFailed(String),

    #[error("PTY I/O error: {0}")]
    IoError(#[from] std::io::Error),

    #[error("Process not found or already terminated")]
    ProcessNotFound,

    #[error("Timeout exceeded: {0:?}")]
    Timeout(Duration),

    #[error("Resource limit exceeded: {0}")]
    ResourceLimit(String),

    #[error("Sandbox denial: {0}")]
    SandboxDenial(String),

    #[error("Policy denial: {0}")]
    PolicyDenial(String),

    #[error("Approval required: {0}")]
    ApprovalRequired(String),
}

/// Process execution request with all parameters for policy check.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct ProcessRequest {
    pub command: String,
    pub args: Vec<String>,
    pub env: HashMap<String, String>,
    pub working_dir: Option<PathBuf>,
    pub origin: ActionOrigin,
}

impl ProcessRequest {
    pub fn new(command: impl Into<String>, origin: ActionOrigin) -> Self {
        Self {
            command: command.into(),
            args: Vec::new(),
            env: HashMap::new(),
            working_dir: None,
            origin,
        }
    }

    pub fn with_args(mut self, args: Vec<String>) -> Self {
        self.args = args;
        self
    }

    pub fn with_env(mut self, env: HashMap<String, String>) -> Self {
        self.env = env;
        self
    }

    pub fn with_working_dir(mut self, working_dir: impl Into<PathBuf>) -> Self {
        self.working_dir = Some(working_dir.into());
        self
    }

    /// Generate a summary for policy decisions.
    fn summary(&self) -> String {
        let mut parts = vec![self.command.clone()];
        if !self.args.is_empty() {
            parts.push(format!("with {} args", self.args.len()));
        }
        if let Some(ref dir) = self.working_dir {
            parts.push(format!("in {}", dir.display()));
        }
        parts.join(" ")
    }

    /// Generate a target string for policy checks.
    fn target(&self) -> String {
        let mut parts = vec![self.command.clone()];
        parts.extend(self.args.iter().cloned());
        parts.join(" ")
    }
}

/// Resource limits for process execution.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct ResourceLimits {
    /// Maximum wall-clock execution time
    pub timeout: Option<Duration>,
    /// Maximum memory in bytes (platform-specific enforcement)
    pub max_memory_bytes: Option<u64>,
    /// CPU time limit in seconds (platform-specific enforcement)
    pub max_cpu_seconds: Option<u64>,
}

impl Default for ResourceLimits {
    fn default() -> Self {
        Self {
            timeout: Some(Duration::from_secs(300)), // 5 minutes default
            max_memory_bytes: None,                   // No memory limit by default
            max_cpu_seconds: None,                    // No CPU limit by default
        }
    }
}

impl ResourceLimits {
    pub fn unlimited() -> Self {
        Self {
            timeout: None,
            max_memory_bytes: None,
            max_cpu_seconds: None,
        }
    }

    pub fn with_timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }
}

/// Handle to a running PTY process.
pub struct PtyProcess {
    master: Box<dyn MasterPty + Send>,
    #[allow(dead_code)]
    child: Box<dyn portable_pty::Child + Send + Sync>,
    reader: Arc<Mutex<Box<dyn Read + Send>>>,
    writer: Arc<Mutex<Box<dyn Write + Send>>>,
}

impl PtyProcess {
    /// Write data to process stdin.
    pub fn write(&self, data: &[u8]) -> Result<usize, PtyError> {
        let mut writer = self.writer.lock().unwrap();
        Ok(writer.write(data)?)
    }

    /// Read available output (non-blocking).
    pub fn read(&self, buf: &mut [u8]) -> Result<usize, PtyError> {
        let mut reader = self.reader.lock().unwrap();
        Ok(reader.read(buf)?)
    }

    /// Send a signal to the process.
    #[cfg(unix)]
    pub fn signal(&self, signal: nix::sys::signal::Signal) -> Result<(), PtyError> {
        use nix::sys::signal::kill;
        use nix::unistd::Pid;

        // Get the child PID - this is platform specific
        // portable-pty doesn't expose PID directly, so we'd need to track it separately
        // For now, return an error indicating this needs implementation
        Err(PtyError::SpawnFailed(
            "Signal support requires PID tracking".into(),
        ))
    }

    #[cfg(not(unix))]
    pub fn signal(&self, _signal: i32) -> Result<(), PtyError> {
        Err(PtyError::SpawnFailed(
            "Signal support is Unix-only".into(),
        ))
    }

    /// Wait for process to complete (blocking).
    pub fn wait(&mut self) -> Result<Option<i32>, PtyError> {
        // The child is behind a trait object, so we can't directly wait
        // This would require refactoring portable-pty usage
        // For now, indicate this is a limitation
        Ok(None)
    }

    /// Attempt to kill the process.
    pub fn kill(&mut self) -> Result<(), PtyError> {
        // Similar to wait, killing requires access to the child process
        Err(PtyError::SpawnFailed(
            "Kill requires child process access".into(),
        ))
    }

    /// Resize the PTY.
    pub fn resize(&self, rows: u16, cols: u16) -> Result<(), PtyError> {
        self.master
            .resize(PtySize {
                rows,
                cols,
                pixel_width: 0,
                pixel_height: 0,
            })
            .map_err(|e| PtyError::IoError(std::io::Error::new(std::io::ErrorKind::Other, e)))
    }
}

/// PTY capability with sandbox and policy integration.
pub struct PtyCapability {
    seam: EffectSeam,
    pty_system: Box<dyn PtySystem>,
}

impl PtyCapability {
    /// Create a new PTY capability with the given effect seam.
    pub fn new(seam: EffectSeam) -> Self {
        Self {
            seam,
            pty_system: portable_pty::native_pty_system(),
        }
    }

    /// Request permission to spawn a process (does not execute).
    pub fn request(
        &self,
        request: &ProcessRequest,
        intent_revision: u64,
    ) -> Result<EffectAdmission, PtyError> {
        let effect = NormalizedEffect {
            origin: request.origin,
            capability: EffectCapability::ProcessSpawn,
            version: CapabilityVersion::V1,
            action: Action {
                origin: request.origin,
                kind: crate::ActionKind::SpawnProcess,
                summary: request.summary(),
                target: Some(request.target()),
            },
        };

        Ok(self.seam.request(effect, intent_revision))
    }

    /// Spawn a PTY process after policy and sandbox checks.
    pub fn spawn(
        &self,
        request: &ProcessRequest,
        limits: ResourceLimits,
    ) -> Result<PtyProcess, PtyError> {
        // Create normalized effect for policy check
        let effect = NormalizedEffect {
            origin: request.origin,
            capability: EffectCapability::ProcessSpawn,
            version: CapabilityVersion::V1,
            action: Action {
                origin: request.origin,
                kind: crate::ActionKind::SpawnProcess,
                summary: request.summary(),
                target: Some(request.target()),
            },
        };

        // Check sandbox and policy
        match self.seam.decide(&effect) {
            crate::EffectDecision::Deny { reason } => {
                return Err(PtyError::SandboxDenial(reason));
            }
            crate::EffectDecision::NeedsApproval { reason } => {
                return Err(PtyError::ApprovalRequired(reason));
            }
            crate::EffectDecision::Allow => {
                // Proceed with spawn
            }
        }

        // Execute the spawn
        self.spawn_internal(request, limits)
    }

    fn spawn_internal(
        &self,
        request: &ProcessRequest,
        _limits: ResourceLimits,
    ) -> Result<PtyProcess, PtyError> {
        // Create PTY with default size
        let pair = self
            .pty_system
            .openpty(PtySize {
                rows: 24,
                cols: 80,
                pixel_width: 0,
                pixel_height: 0,
            })
            .map_err(|e| PtyError::SpawnFailed(format!("Failed to open PTY: {}", e)))?;

        // Build command
        let mut cmd = CommandBuilder::new(&request.command);
        cmd.args(&request.args);

        // Set environment variables
        for (key, value) in &request.env {
            cmd.env(key, value);
        }

        // Set working directory
        if let Some(ref dir) = request.working_dir {
            cmd.cwd(dir);
        }

        // Spawn the child process
        let child = pair
            .slave
            .spawn_command(cmd)
            .map_err(|e| PtyError::SpawnFailed(format!("Failed to spawn: {}", e)))?;

        // Get reader and writer from master
        let reader = pair.master.try_clone_reader().map_err(|e| {
            PtyError::SpawnFailed(format!("Failed to clone reader: {}", e))
        })?;

        let writer = pair.master.take_writer().map_err(|e| {
            PtyError::SpawnFailed(format!("Failed to take writer: {}", e))
        })?;

        Ok(PtyProcess {
            master: pair.master,
            child,
            reader: Arc::new(Mutex::new(reader)),
            writer: Arc::new(Mutex::new(writer)),
        })
    }
}

/// High-level PTY executor that handles approval workflow.
pub struct PtyExecutor {
    capability: PtyCapability,
}

impl PtyExecutor {
    pub fn new(seam: EffectSeam) -> Self {
        Self {
            capability: PtyCapability::new(seam),
        }
    }

    /// Execute a process with automatic approval handling.
    pub fn execute(
        &self,
        request: &ProcessRequest,
        limits: ResourceLimits,
    ) -> Result<PtyProcess, PtyError> {
        self.capability.spawn(request, limits)
    }

    /// Request permission without executing.
    pub fn request(
        &self,
        request: &ProcessRequest,
        intent_revision: u64,
    ) -> Result<EffectAdmission, PtyError> {
        self.capability.request(request, intent_revision)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{EffectSeam, PolicyEngine, SandboxScope};
    use std::io::Write as _;

    fn temp_workspace() -> PathBuf {
        let root = std::env::temp_dir().join(format!("pty-test-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&root).expect("create workspace");
        root
    }

    #[test]
    fn process_request_generates_correct_summary() {
        let request = ProcessRequest::new("ls", ActionOrigin::Agent)
            .with_args(vec!["-la".into()])
            .with_working_dir("/tmp");

        let summary = request.summary();
        assert!(summary.contains("ls"));
        assert!(summary.contains("1 args"));
        assert!(summary.contains("/tmp"));
    }

    #[test]
    fn resource_limits_default_has_timeout() {
        let limits = ResourceLimits::default();
        assert!(limits.timeout.is_some());
        assert_eq!(limits.timeout.unwrap(), Duration::from_secs(300));
    }

    #[test]
    fn pty_capability_denies_agent_spawn_without_approval() {
        let root = temp_workspace();
        let seam = EffectSeam::workspace_full(&root);
        let capability = PtyCapability::new(seam);

        let request = ProcessRequest::new("echo", ActionOrigin::Agent)
            .with_args(vec!["test".into()]);

        let result = capability.spawn(&request, ResourceLimits::default());
        assert!(matches!(result, Err(PtyError::ApprovalRequired(_))));
    }

    #[test]
    fn pty_capability_allows_user_spawn() {
        let root = temp_workspace();
        let seam = EffectSeam::workspace_full(&root);
        let capability = PtyCapability::new(seam);

        let request = ProcessRequest::new("echo", ActionOrigin::User)
            .with_args(vec!["test".into()]);

        // User-originated processes are allowed by policy
        let result = capability.spawn(&request, ResourceLimits::default());
        assert!(result.is_ok());
    }

    #[test]
    fn pty_process_can_write_and_read() {
        let root = temp_workspace();
        let seam = EffectSeam::workspace_full(&root);
        let capability = PtyCapability::new(seam);

        let request = ProcessRequest::new("cat", ActionOrigin::User);

        let mut process = capability
            .spawn(&request, ResourceLimits::default())
            .expect("spawn cat");

        // Write to stdin
        let written = process.write(b"hello\n").expect("write to stdin");
        assert!(written > 0);

        // Give the process time to echo
        std::thread::sleep(Duration::from_millis(100));

        // Read from stdout
        let mut buf = [0u8; 1024];
        let read = process.read(&mut buf).expect("read from stdout");
        assert!(read > 0);

        // Output should contain our input
        let output = std::str::from_utf8(&buf[..read]).unwrap();
        assert!(output.contains("hello"));
    }

    #[test]
    fn pty_process_resize_succeeds() {
        let root = temp_workspace();
        let seam = EffectSeam::workspace_full(&root);
        let capability = PtyCapability::new(seam);

        let request = ProcessRequest::new("cat", ActionOrigin::User);

        let process = capability
            .spawn(&request, ResourceLimits::default())
            .expect("spawn cat");

        let result = process.resize(40, 120);
        assert!(result.is_ok());
    }

    #[test]
    fn pty_executor_respects_sandbox() {
        let root = temp_workspace();
        let policy = PolicyEngine::new(SandboxScope::local_workspace(&root));
        let sandbox = Sandbox::unavailable("test sandbox denial");
        let seam = EffectSeam::with_sandbox(policy, sandbox);
        let executor = PtyExecutor::new(seam);

        let request = ProcessRequest::new("echo", ActionOrigin::User)
            .with_args(vec!["test".into()]);

        let result = executor.execute(&request, ResourceLimits::default());
        assert!(matches!(result, Err(PtyError::SandboxDenial(_))));
    }

    #[test]
    fn pty_request_returns_needs_approval_for_agent() {
        let root = temp_workspace();
        let seam = EffectSeam::workspace_full(&root);
        let executor = PtyExecutor::new(seam);

        let request = ProcessRequest::new("cargo", ActionOrigin::Agent)
            .with_args(vec!["fmt".into()]);

        let admission = executor.request(&request, 1).expect("request admission");
        assert!(matches!(admission, EffectAdmission::NeedsApproval(_)));
    }

    #[test]
    fn pty_request_returns_allow_for_user() {
        let root = temp_workspace();
        let seam = EffectSeam::workspace_full(&root);
        let executor = PtyExecutor::new(seam);

        let request = ProcessRequest::new("ls", ActionOrigin::User);

        let admission = executor.request(&request, 1).expect("request admission");
        assert!(matches!(admission, EffectAdmission::Allow));
    }
}

