//! SFTP client for remote file access.
//!
//! Provides secure file operations over SSH with policy checks,
//! sandbox validation, and exact approval for write operations.

use crate::approval::{ApprovalRequest, ApprovalResolution, ApprovalState};
use crate::policy::{Action, ActionFingerprint, ActionKind, ActionOrigin, PolicyDecision, PolicyEngine};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};
use thiserror::Error;

/// SFTP operation type for policy checking.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SftpOperation {
    Read,
    Write,
    List,
    Delete,
}

impl SftpOperation {
    pub fn is_mutating(&self) -> bool {
        matches!(self, Self::Write | Self::Delete)
    }
}

/// SSH profile for SFTP connection.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SshProfile {
    pub id: String,
    pub display_name: String,
    pub host: String,
    pub port: u16,
    pub username: String,
    /// Host key fingerprint for verification (SHA256).
    pub host_key_fingerprint: Option<String>,
}

impl SshProfile {
    pub fn new(
        id: impl Into<String>,
        display_name: impl Into<String>,
        host: impl Into<String>,
        username: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            display_name: display_name.into(),
            host: host.into(),
            port: 22,
            username: username.into(),
            host_key_fingerprint: None,
        }
    }

    pub fn with_port(mut self, port: u16) -> Self {
        self.port = port;
        self
    }

    pub fn with_host_key(mut self, fingerprint: impl Into<String>) -> Self {
        self.host_key_fingerprint = Some(fingerprint.into());
        self
    }

    pub fn validate(&self) -> Result<(), SftpError> {
        if self.id.trim().is_empty() {
            return Err(SftpError::InvalidProfile("id is required".into()));
        }
        if self.host.trim().is_empty() {
            return Err(SftpError::InvalidProfile("host is required".into()));
        }
        if self.username.trim().is_empty() {
            return Err(SftpError::InvalidProfile("username is required".into()));
        }
        if self.port == 0 {
            return Err(SftpError::InvalidProfile("invalid port".into()));
        }
        Ok(())
    }

    pub fn target(&self) -> String {
        format!("{}@{}:{}", self.username, self.host, self.port)
    }
}

/// Content fingerprint for exact approval matching.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ContentFingerprint(String);

impl ContentFingerprint {
    pub fn from_bytes(content: &[u8]) -> Self {
        let digest = Sha256::digest(content);
        Self(digest.iter().map(|byte| format!("{byte:02x}")).collect())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// SFTP file metadata.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SftpFileMetadata {
    pub path: PathBuf,
    pub size: u64,
    pub is_dir: bool,
    pub modified: Option<u64>,
}

/// SFTP operation request with policy context.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SftpRequest {
    pub profile: SshProfile,
    pub operation: SftpOperation,
    pub remote_path: PathBuf,
    /// Content fingerprint for write operations.
    pub content_fingerprint: Option<ContentFingerprint>,
    /// Content size for write operations.
    pub content_size: Option<u64>,
}

impl SftpRequest {
    pub fn read(profile: SshProfile, remote_path: impl Into<PathBuf>) -> Self {
        Self {
            profile,
            operation: SftpOperation::Read,
            remote_path: remote_path.into(),
            content_fingerprint: None,
            content_size: None,
        }
    }

    pub fn write(
        profile: SshProfile,
        remote_path: impl Into<PathBuf>,
        content: &[u8],
    ) -> Self {
        Self {
            profile,
            operation: SftpOperation::Write,
            remote_path: remote_path.into(),
            content_fingerprint: Some(ContentFingerprint::from_bytes(content)),
            content_size: Some(content.len() as u64),
        }
    }

    pub fn list(profile: SshProfile, remote_path: impl Into<PathBuf>) -> Self {
        Self {
            profile,
            operation: SftpOperation::List,
            remote_path: remote_path.into(),
            content_fingerprint: None,
            content_size: None,
        }
    }

    pub fn delete(profile: SshProfile, remote_path: impl Into<PathBuf>) -> Self {
        Self {
            profile,
            operation: SftpOperation::Delete,
            remote_path: remote_path.into(),
            content_fingerprint: None,
            content_size: None,
        }
    }

    /// Convert to Action for policy evaluation.
    pub fn to_action(&self, origin: ActionOrigin) -> Action {
        let summary = format!(
            "SFTP {:?} {} on {}",
            self.operation,
            self.remote_path.display(),
            self.profile.target()
        );
        Action {
            origin,
            kind: ActionKind::SftpTransfer,
            summary,
            target: Some(format!(
                "{}:{}",
                self.profile.target(),
                self.remote_path.display()
            )),
        }
    }
}

/// SFTP client with policy enforcement.
#[derive(Debug)]
pub struct SftpClient {
    policy: PolicyEngine,
    /// Stored approvals for exact matching.
    approvals: std::collections::HashMap<ActionFingerprint, ApprovalResolution>,
}

impl SftpClient {
    pub fn new(policy: PolicyEngine) -> Self {
        Self {
            policy,
            approvals: std::collections::HashMap::new(),
        }
    }

    /// Register an approval resolution for future operations.
    pub fn register_approval(&mut self, resolution: ApprovalResolution) {
        self.approvals.insert(resolution.action_fingerprint.clone(), resolution);
    }

    /// Check if an operation is allowed by policy.
    pub fn check_policy(&self, request: &SftpRequest, origin: ActionOrigin) -> PolicyDecision {
        // Validate profile first
        if let Err(e) = request.profile.validate() {
            return PolicyDecision::Deny {
                reason: format!("invalid SSH profile: {}", e),
            };
        }

        // Check network policy
        let action = request.to_action(origin);
        let decision = self.policy.evaluate(&action);

        // Additional SFTP-specific checks
        if matches!(decision, PolicyDecision::Allow | PolicyDecision::NeedsApproval { .. }) {
            // Mutating operations require sandbox check
            if request.operation.is_mutating() {
                return PolicyDecision::NeedsApproval {
                    reason: format!(
                        "mutating SFTP {:?} operation on remote host {}",
                        request.operation,
                        request.profile.host
                    ),
                };
            }
        }

        decision
    }

    /// Check if an exact approval exists for this request.
    pub fn has_approval(&self, request: &SftpRequest, origin: ActionOrigin) -> bool {
        let action = request.to_action(origin);
        let fingerprint = action.fingerprint();

        self.approvals
            .get(&fingerprint)
            .map(|res| res.accepted)
            .unwrap_or(false)
    }

    /// Create an approval request for a SFTP operation.
    pub fn create_approval_request(
        &self,
        request: &SftpRequest,
        origin: ActionOrigin,
        intent_revision: u64,
    ) -> ApprovalRequest {
        let action = request.to_action(origin);
        let mut reason = format!(
            "SFTP {:?} operation on {}",
            request.operation,
            request.profile.target()
        );

        if let Some(ref fingerprint) = request.content_fingerprint {
            reason.push_str(&format!("\nContent SHA256: {}", fingerprint.as_str()));
        }
        if let Some(size) = request.content_size {
            reason.push_str(&format!("\nSize: {} bytes", size));
        }

        ApprovalRequest::pending(action, reason, intent_revision)
    }

    /// Perform SFTP read operation (mock implementation).
    pub async fn read(&self, request: &SftpRequest, origin: ActionOrigin) -> Result<Vec<u8>, SftpError> {
        // Policy check
        match self.check_policy(request, origin) {
            PolicyDecision::Allow => {},
            PolicyDecision::NeedsApproval { reason } => {
                if !self.has_approval(request, origin) {
                    return Err(SftpError::ApprovalRequired(reason));
                }
            }
            PolicyDecision::Deny { reason } => {
                return Err(SftpError::PolicyDenied(reason));
            }
        }

        // Mock implementation - actual SSH/SFTP would happen here
        Err(SftpError::NotImplemented("SFTP read operation requires SSH library integration".into()))
    }

    /// Perform SFTP write operation (mock implementation).
    pub async fn write(
        &self,
        request: &SftpRequest,
        content: &[u8],
        origin: ActionOrigin,
    ) -> Result<(), SftpError> {
        // Verify content fingerprint matches
        if let Some(ref expected) = request.content_fingerprint {
            let actual = ContentFingerprint::from_bytes(content);
            if &actual != expected {
                return Err(SftpError::ContentMismatch {
                    expected: expected.clone(),
                    actual,
                });
            }
        }

        // Policy check (mutating operations always need approval)
        match self.check_policy(request, origin) {
            PolicyDecision::Allow => {
                // Even if policy allows, mutating ops need explicit approval
                if !self.has_approval(request, origin) {
                    return Err(SftpError::ApprovalRequired(
                        "mutating SFTP operation requires explicit approval".into()
                    ));
                }
            },
            PolicyDecision::NeedsApproval { reason } => {
                if !self.has_approval(request, origin) {
                    return Err(SftpError::ApprovalRequired(reason));
                }
            }
            PolicyDecision::Deny { reason } => {
                return Err(SftpError::PolicyDenied(reason));
            }
        }

        // Mock implementation - actual SSH/SFTP would happen here
        Err(SftpError::NotImplemented("SFTP write operation requires SSH library integration".into()))
    }

    /// Perform SFTP list operation (mock implementation).
    pub async fn list(&self, request: &SftpRequest, origin: ActionOrigin) -> Result<Vec<SftpFileMetadata>, SftpError> {
        // Policy check
        match self.check_policy(request, origin) {
            PolicyDecision::Allow => {},
            PolicyDecision::NeedsApproval { reason } => {
                if !self.has_approval(request, origin) {
                    return Err(SftpError::ApprovalRequired(reason));
                }
            }
            PolicyDecision::Deny { reason } => {
                return Err(SftpError::PolicyDenied(reason));
            }
        }

        // Mock implementation - actual SSH/SFTP would happen here
        Err(SftpError::NotImplemented("SFTP list operation requires SSH library integration".into()))
    }

    /// Perform SFTP delete operation (mock implementation).
    pub async fn delete(&self, request: &SftpRequest, origin: ActionOrigin) -> Result<(), SftpError> {
        // Policy check (mutating operations always need approval)
        match self.check_policy(request, origin) {
            PolicyDecision::Allow => {
                // Even if policy allows, mutating ops need explicit approval
                if !self.has_approval(request, origin) {
                    return Err(SftpError::ApprovalRequired(
                        "mutating SFTP operation requires explicit approval".into()
                    ));
                }
            },
            PolicyDecision::NeedsApproval { reason } => {
                if !self.has_approval(request, origin) {
                    return Err(SftpError::ApprovalRequired(reason));
                }
            }
            PolicyDecision::Deny { reason } => {
                return Err(SftpError::PolicyDenied(reason));
            }
        }

        // Mock implementation - actual SSH/SFTP would happen here
        Err(SftpError::NotImplemented("SFTP delete operation requires SSH library integration".into()))
    }
}

#[derive(Debug, Error)]
pub enum SftpError {
    #[error("Invalid SSH profile: {0}")]
    InvalidProfile(String),

    #[error("Policy denied: {0}")]
    PolicyDenied(String),

    #[error("Approval required: {0}")]
    ApprovalRequired(String),

    #[error("Content fingerprint mismatch: expected {expected:?}, got {actual:?}")]
    ContentMismatch {
        expected: ContentFingerprint,
        actual: ContentFingerprint,
    },

    #[error("Not implemented: {0}")]
    NotImplemented(String),

    #[error("SSH connection failed: {0}")]
    ConnectionFailed(String),

    #[error("SFTP operation failed: {0}")]
    OperationFailed(String),
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::policy::SandboxScope;

    fn test_profile() -> SshProfile {
        SshProfile::new("test-ssh", "Test SSH", "example.com", "testuser")
    }

    fn network_enabled_policy() -> PolicyEngine {
        let mut scope = SandboxScope::local_workspace(std::env::current_dir().unwrap());
        scope.allow_network = true;
        scope.allowed_hosts = vec!["example.com".into()];
        PolicyEngine::new(scope)
    }

    fn network_disabled_policy() -> PolicyEngine {
        PolicyEngine::new(SandboxScope::local_workspace(std::env::current_dir().unwrap()))
    }

    #[test]
    fn ssh_profile_validation_requires_fields() {
        let mut profile = test_profile();
        profile.id = "".into();
        assert!(profile.validate().is_err());

        let mut profile = test_profile();
        profile.host = "".into();
        assert!(profile.validate().is_err());

        let mut profile = test_profile();
        profile.username = "".into();
        assert!(profile.validate().is_err());
    }

    #[test]
    fn ssh_profile_formats_target() {
        let profile = test_profile();
        assert_eq!(profile.target(), "testuser@example.com:22");
    }

    #[test]
    fn content_fingerprint_is_deterministic() {
        let content = b"hello world";
        let fp1 = ContentFingerprint::from_bytes(content);
        let fp2 = ContentFingerprint::from_bytes(content);
        assert_eq!(fp1, fp2);
    }

    #[test]
    fn content_fingerprint_differs_for_different_content() {
        let fp1 = ContentFingerprint::from_bytes(b"hello");
        let fp2 = ContentFingerprint::from_bytes(b"world");
        assert_ne!(fp1, fp2);
    }

    #[test]
    fn sftp_request_creates_correct_action() {
        let profile = test_profile();
        let request = SftpRequest::read(profile.clone(), "/remote/file.txt");
        let action = request.to_action(ActionOrigin::Agent);

        assert_eq!(action.kind, ActionKind::SftpTransfer);
        assert!(action.summary.contains("Read"));
        assert!(action.target.is_some());
    }

    #[test]
    fn network_disabled_denies_sftp() {
        let policy = network_disabled_policy();
        let client = SftpClient::new(policy);
        let profile = test_profile();
        let request = SftpRequest::read(profile, "/test.txt");

        let decision = client.check_policy(&request, ActionOrigin::Agent);
        assert!(matches!(decision, PolicyDecision::Deny { .. }));
    }

    #[test]
    fn mutating_operations_require_approval() {
        let policy = network_enabled_policy();
        let client = SftpClient::new(policy);
        let profile = test_profile();

        let write_request = SftpRequest::write(profile.clone(), "/test.txt", b"content");
        let decision = client.check_policy(&write_request, ActionOrigin::Agent);
        assert!(matches!(decision, PolicyDecision::NeedsApproval { .. }));

        let delete_request = SftpRequest::delete(profile, "/test.txt");
        let decision = client.check_policy(&delete_request, ActionOrigin::Agent);
        assert!(matches!(decision, PolicyDecision::NeedsApproval { .. }));
    }

    #[test]
    fn read_operations_need_approval_for_network() {
        let policy = network_enabled_policy();
        let client = SftpClient::new(policy);
        let profile = test_profile();
        let request = SftpRequest::read(profile, "/test.txt");

        let decision = client.check_policy(&request, ActionOrigin::Agent);
        assert!(matches!(decision, PolicyDecision::NeedsApproval { .. }));
    }

    #[tokio::test]
    async fn write_without_approval_fails() {
        let policy = network_enabled_policy();
        let client = SftpClient::new(policy);
        let profile = test_profile();
        let content = b"test content";
        let request = SftpRequest::write(profile, "/test.txt", content);

        let result = client.write(&request, content, ActionOrigin::Agent).await;
        assert!(matches!(result, Err(SftpError::ApprovalRequired(_))));
    }

    #[tokio::test]
    async fn write_with_mismatched_content_fails() {
        let policy = network_enabled_policy();
        let mut client = SftpClient::new(policy);
        let profile = test_profile();

        let original_content = b"original content";
        let request = SftpRequest::write(profile, "/test.txt", original_content);

        // Grant approval
        let approval_req = client.create_approval_request(&request, ActionOrigin::Agent, 1);
        let resolution = ApprovalResolution::user(&approval_req, true);
        client.register_approval(resolution);

        // Try to write different content
        let different_content = b"different content";
        let result = client.write(&request, different_content, ActionOrigin::Agent).await;
        assert!(matches!(result, Err(SftpError::ContentMismatch { .. })));
    }

    #[test]
    fn approval_request_includes_content_fingerprint() {
        let policy = network_enabled_policy();
        let client = SftpClient::new(policy);
        let profile = test_profile();
        let content = b"test content";
        let request = SftpRequest::write(profile, "/test.txt", content);

        let approval_req = client.create_approval_request(&request, ActionOrigin::Agent, 1);
        assert!(approval_req.reason.contains("SHA256"));
        assert!(approval_req.reason.contains("bytes"));
    }

    #[test]
    fn approval_registration_enables_operation() {
        let policy = network_enabled_policy();
        let mut client = SftpClient::new(policy);
        let profile = test_profile();
        let request = SftpRequest::read(profile, "/test.txt");

        // Initially no approval
        assert!(!client.has_approval(&request, ActionOrigin::Agent));

        // Register approval
        let approval_req = client.create_approval_request(&request, ActionOrigin::Agent, 1);
        let resolution = ApprovalResolution::user(&approval_req, true);
        client.register_approval(resolution);

        // Now has approval
        assert!(client.has_approval(&request, ActionOrigin::Agent));
    }

    #[test]
    fn rejected_approval_does_not_enable_operation() {
        let policy = network_enabled_policy();
        let mut client = SftpClient::new(policy);
        let profile = test_profile();
        let request = SftpRequest::read(profile, "/test.txt");

        let approval_req = client.create_approval_request(&request, ActionOrigin::Agent, 1);
        let resolution = ApprovalResolution::user(&approval_req, false);
        client.register_approval(resolution);

        // Rejected approval does not enable
        assert!(!client.has_approval(&request, ActionOrigin::Agent));
    }

    #[test]
    fn different_requests_have_different_fingerprints() {
        let policy = network_enabled_policy();
        let client = SftpClient::new(policy);
        let profile = test_profile();

        let req1 = SftpRequest::read(profile.clone(), "/file1.txt");
        let req2 = SftpRequest::read(profile, "/file2.txt");

        let action1 = req1.to_action(ActionOrigin::Agent);
        let action2 = req2.to_action(ActionOrigin::Agent);

        assert_ne!(action1.fingerprint(), action2.fingerprint());
    }

    #[test]
    fn invalid_profile_is_denied() {
        let policy = network_enabled_policy();
        let client = SftpClient::new(policy);

        let mut profile = test_profile();
        profile.host = "".into();
        let request = SftpRequest::read(profile, "/test.txt");

        let decision = client.check_policy(&request, ActionOrigin::Agent);
        assert!(matches!(decision, PolicyDecision::Deny { .. }));
    }
}

//! Remote access capabilities: SSH, SFTP, tmux.

pub mod sftp;

pub use sftp::{
    ContentFingerprint, SftpClient, SftpError, SftpFileMetadata, SftpOperation, SftpRequest,
    SshProfile,
};

